    time_bin_s: float = 0.1
    temporal_smooth_bins: float = 3.0
    require_full_valid_bin: bool = True
    moving_speed_threshold: float = 3.0
    direction_predictor: str = "head"
    session_mode: str = "session1"
    min_total_spikes: int = 10
    standardize: bool = True
    include_accel: bool = False
    include_session_covariate: bool = False
    use_regularization: bool = True
    reg_alpha: float = 0.1
    reg_l1_wt: float = 0.0
    arena_size_cm: tuple[float, float] = (35.5, 20.0)
    rbf_grid: tuple[int, int] = (7, 4)
    rbf_sigma_cm: float = 6.0
    predicted_map_min_occupancy_bins: float = 2.0

    @property
    def selected_session_indices(self) -> tuple[int, ...]:
        mode = str(self.session_mode).strip().lower()
        if mode == "session1":
            return (0,)
        if mode == "combined_s1_s2":
            return (0, 1)
        raise ValueError(
            f"Unsupported session_mode '{self.session_mode}'. "
            "Use 'session1' or 'combined_s1_s2'."
        )


