def _load_merged_data(animal_dir: Path) -> dict[str, Any]:
    primary = animal_dir / "merged_aligned_data.pkl"
    fallback = animal_dir / "merged_aligned_data_CS.pkl"
    src = primary if primary.exists() else fallback
    if not src.exists():
        raise FileNotFoundError(f"Missing merged data for {animal_dir.name}")
    import pickle

    with src.open("rb") as f:
        return pickle.load(f)


def _compute_bad_masks(
    merged_data: dict[str, Any],
    snr_threshold: float,
    min_good_minutes: float = 5.0,
    *,
    return_stats: bool = False,
) -> np.ndarray | tuple[np.ndarray, list[dict[str, Any]]]:
    x_neural = np.asarray(merged_data["x_neural"], dtype=float)
    y_neural = np.asarray(merged_data.get("y_neural", np.full_like(x_neural, np.nan)), dtype=float)
    speed = np.asarray(merged_data.get("speed", np.full_like(x_neural, np.nan)), dtype=float)
    frame_rate = float(merged_data.get("frame_rate", np.nan))
    pos_nan_mask = (~np.isfinite(x_neural)) | (~np.isfinite(y_neural)) | (~np.isfinite(speed))
    traces_snr = merged_data.get("traces_SNR_interpolated", merged_data.get("traces", []))
    all_spikes = merged_data.get("all_spikes", merged_data.get("spikes", []))
    complex_bursts_dicts = merged_data.get("complex_bursts_dicts", [])
    n_cells = len(merged_data["spikes"])
    bad_masks: list[np.ndarray] = []
    mask_stats: list[dict[str, Any]] = []

    if not np.isfinite(frame_rate) or frame_rate <= 0:
        frame_rate = 1.0

    for cell_idx in range(n_cells):
        trace = np.asarray(traces_snr[cell_idx], dtype=float) if cell_idx < len(traces_snr) else np.array([])
        spks = np.asarray(all_spikes[cell_idx], dtype=int) if cell_idx < len(all_spikes) else np.array([], dtype=int)
        cb = complex_bursts_dicts[cell_idx] if cell_idx < len(complex_bursts_dicts) else None

        if trace.ndim != 1 or trace.size != x_neural.size:
            # Exclude malformed traces from downstream analysis.
            bad_mask = np.ones(x_neural.size, dtype=bool)
            bad_masks.append(bad_mask)
            removed_total = int(np.sum(bad_mask))
            removed_pos_nan = int(np.sum(bad_mask & pos_nan_mask))
            removed_snr_only = int(np.sum(bad_mask & (~pos_nan_mask)))
            mask_stats.append(
                {
                    "cell_idx": int(cell_idx),
                    "n_frames_total": int(x_neural.size),
                    "n_good_frames_before_min_minutes": 0,
                    "good_minutes_before_min_minutes": 0.0,
                    "removed_by_min_good_minutes": True,
                    "eligible_cell": False,
                    "n_removed_frames_total": removed_total,
                    "n_removed_frames_pos_nan": removed_pos_nan,
                    "n_removed_frames_snr_only": removed_snr_only,
                    "pct_removed_frames_total": (100.0 * removed_total / x_neural.size) if x_neural.size > 0 else np.nan,
                    "pct_removed_frames_snr_only": (100.0 * removed_snr_only / x_neural.size) if x_neural.size > 0 else np.nan,
                }
            )
            continue

        snr_vals = np.array([], dtype=float)
        try:
            snr_res = compute_time_varying_snr_from_trace(
                trace=trace,
                spks=spks,
                complex_burst_dict=cb,
                sampling_rate_hz=frame_rate,
                isi_threshold_ms=20,
                spike_baseline_points=3,
                spike_remove_points=3,
                baseline_window_seconds=10,
                plot_single_cell=False,
            )
            snr_vals = np.asarray(snr_res.get("snr_time_varying", []), dtype=float)
        except Exception as exc:
            raise RuntimeError(
                f"Time-varying SNR failed for cell {cell_idx}: {exc}"
            ) from exc

        if snr_vals.ndim != 1 or snr_vals.size != x_neural.size:
            raise RuntimeError(
                f"Invalid time-varying SNR shape for cell {cell_idx}: "
                f"expected {x_neural.size}, got {snr_vals.size}"
            )
        else:
            good_snr = np.isfinite(snr_vals) & (snr_vals >= snr_threshold)
            n_good_before = int(np.sum(good_snr))
            good_minutes = float(n_good_before) / float(frame_rate) / 60.0
            removed_by_min_minutes = bool(good_minutes < float(min_good_minutes))
            if removed_by_min_minutes:
                good_snr[:] = False
            bad_mask = (~good_snr) | pos_nan_mask
        bad_mask = np.asarray(bad_mask, dtype=bool)
        bad_masks.append(bad_mask)

        removed_total = int(np.sum(bad_mask))
        removed_pos_nan = int(np.sum(bad_mask & pos_nan_mask))
        removed_snr_only = int(np.sum(bad_mask & (~pos_nan_mask)))
        eligible_cell = bool(np.any(~bad_mask))
        mask_stats.append(
            {
                "cell_idx": int(cell_idx),
                "n_frames_total": int(x_neural.size),
                "n_good_frames_before_min_minutes": n_good_before,
                "good_minutes_before_min_minutes": good_minutes,
                "removed_by_min_good_minutes": removed_by_min_minutes,
                "eligible_cell": eligible_cell,
                "n_removed_frames_total": removed_total,
                "n_removed_frames_pos_nan": removed_pos_nan,
                "n_removed_frames_snr_only": removed_snr_only,
                "pct_removed_frames_total": (100.0 * removed_total / x_neural.size) if x_neural.size > 0 else np.nan,
                "pct_removed_frames_snr_only": (100.0 * removed_snr_only / x_neural.size) if x_neural.size > 0 else np.nan,
            }
        )

    bad_masks_arr = np.asarray(bad_masks)
    if return_stats:
        return bad_masks_arr, mask_stats
    return bad_masks_arr


def _build_complex_mask(n_frames: int, cb_dict: dict[str, Any] | None) -> np.ndarray:
    out = np.zeros(n_frames, dtype=bool)
    if not isinstance(cb_dict, dict):
        return out
    starts = np.asarray(cb_dict.get("starts", []), dtype=int)
    ends = np.asarray(cb_dict.get("ends", []), dtype=int)
    n = min(len(starts), len(ends))
    for i in range(n):
        s = max(0, int(starts[i]))
        e = min(n_frames - 1, int(ends[i]))
        if e >= s:
            out[s : e + 1] = True
    return out


def _enforce_min_gap(indices: np.ndarray, min_gap_frames: int) -> np.ndarray:
    if indices.size == 0:
        return indices
    keep = [int(indices[0])]
    for idx in indices[1:]:
        if int(idx) - keep[-1] >= min_gap_frames:
            keep.append(int(idx))
    return np.asarray(keep, dtype=int)


def _event_psd_chunks(
    trace: np.ndarray,
    centers: np.ndarray,
    state_mask: np.ndarray,
    chunk_frames: int,
    frame_rate: float,
    nperseg: int,
    noverlap: int,
    min_valid_fraction: float,
) -> tuple[np.ndarray | None, list[np.ndarray]]:
    if centers.size == 0:
        return None, []
    half = chunk_frames // 2
    chunks: list[np.ndarray] = []
    freqs_ref = None

    for center in centers:
        start = int(center) - half
        end = start + chunk_frames
        if start < 0 or end > trace.size:
            continue
        chunk_state = state_mask[start:end]
        valid_fraction = float(np.mean(chunk_state))
        if valid_fraction < min_valid_fraction:
            continue
        if min_valid_fraction >= 1.0 and not np.all(chunk_state):
            continue
        seg = trace[start:end]
        if not np.all(np.isfinite(seg)):
            continue
        freqs, pxx = signal.welch(
            seg,
            fs=frame_rate,
            nperseg=nperseg,
            noverlap=noverlap,
            detrend="constant",
        )
        freqs_ref = freqs
        chunks.append(pxx)
    return freqs_ref, chunks


def _mask_to_psd_chunks(
    trace: np.ndarray,
    mask: np.ndarray,
    chunk_frames: int,
    frame_rate: float,
    nperseg: int,
    noverlap: int,
) -> tuple[np.ndarray | None, list[np.ndarray]]:
    freqs_ref = None
    chunks: list[np.ndarray] = []
    if chunk_frames <= 0:
        return freqs_ref, chunks

    in_epoch = False
    start_idx = 0
    epochs: list[tuple[int, int]] = []
    for i, flag in enumerate(mask):
        if flag and not in_epoch:
            start_idx = i
            in_epoch = True
        elif not flag and in_epoch:
            epochs.append((start_idx, i - 1))
            in_epoch = False
    if in_epoch:
        epochs.append((start_idx, len(mask) - 1))

    for start, end in epochs:
        length = end - start + 1
        if length < chunk_frames:
            continue
        for seg_start in range(start, end - chunk_frames + 2, chunk_frames):
            seg = trace[seg_start : seg_start + chunk_frames]
            if not np.all(np.isfinite(seg)):
                continue
            freqs, pxx = signal.welch(
                seg,
                fs=frame_rate,
                nperseg=nperseg,
                noverlap=noverlap,
                detrend="constant",
            )
            freqs_ref = freqs
            chunks.append(pxx)
    return freqs_ref, chunks


def _stack_psd_rows(rows: list[np.ndarray], n_freq: int) -> np.ndarray:
    if not rows:
        return np.empty((0, n_freq), dtype=float)
    return np.vstack(rows)


def generate_psd_burst_type_state_npz(animal_id: str, config: PipelineConfig) -> Path:
    animal_dir = config.data_root / animal_id
    out_path = animal_dir / f"psd_burstType_state_speed{int(config.pooled.psd_speed_threshold)}.npz"

    merged = _load_merged_data(animal_dir)
    frame_rate = float(merged["frame_rate"])
    speed = np.asarray(merged["speed"], dtype=float)
    x_neural = np.asarray(merged["x_neural"], dtype=float)
    y_neural = np.asarray(merged["y_neural"], dtype=float)
    vms = np.asarray(merged["Vm_SNR_interpolated"], dtype=object)
    refined_ss = merged.get("refined_SS", [])
    cb_dicts = merged.get("complex_bursts_dicts", [])

    bad_masks = _compute_bad_masks(
        merged,
        config.analysis.snr_threshold,
        config.analysis.min_good_minutes,
    )

    chunk_frames = max(4, int(round(config.pooled.psd_chunk_s * frame_rate)))
    nperseg = max(4, min(chunk_frames, int(round(config.pooled.psd_nperseg_s * frame_rate))))
    noverlap = int(round(nperseg * config.pooled.psd_noverlap_frac))
    noverlap = min(noverlap, nperseg - 1)

    simple_window = max(1, int(round(config.pooled.simple_event_window_ms * frame_rate / 1000.0)))
    min_gap_frames = max(1, int(round(config.pooled.simple_event_min_gap_ms * frame_rate / 1000.0)))

    cond_to_npz = {
        ("moving", "complex"): "psd_moving_complex",
        ("moving", "simple"): "psd_moving_simple",
        ("quiet", "complex"): "psd_quiet_complex",
        ("quiet", "simple"): "psd_quiet_simple",
        ("moving", "non_burst"): "psd_moving_nonburst",
        ("quiet", "non_burst"): "psd_quiet_nonburst",
    }

    psd_rows: dict[str, list[np.ndarray]] = {npz_key: [] for npz_key in cond_to_npz.values()}
    cell_indices: dict[str, list[int]] = {npz_key: [] for npz_key in cond_to_npz.values()}
    freqs_ref = None

    n_cells = len(vms)
    for cell_idx in range(n_cells):
        trace = np.asarray(vms[cell_idx], dtype=float)
        if trace.ndim != 1 or trace.size != speed.size:
            continue
        if np.any(~np.isfinite(trace)) and np.any(np.isfinite(trace)):
            trace = core.interpolate_nan_segment(trace)

        valid_frames = np.isfinite(speed) & np.isfinite(x_neural) & np.isfinite(y_neural)
        if cell_idx < bad_masks.shape[0]:
            valid_frames &= ~bad_masks[cell_idx]

        speed_for_epochs = speed.copy()
        speed_for_epochs[~valid_frames] = np.nan
        _, _, moving_idx = core._compute_moving_epochs(
            speed_for_epochs,
            frame_rate,
            kernel_size=config.analysis.kernel_size,
            filter_type="boxcar",
            speed_threshold=config.pooled.psd_speed_threshold,
            min_duration_s=config.analysis.min_duration_s,
            merge_gap_s=config.analysis.merge_gap_s,
        )

        moving_mask = np.zeros(speed.size, dtype=bool)
        if len(moving_idx) > 0:
            moving_mask[np.asarray(moving_idx, dtype=int)] = True
        moving_mask &= valid_frames
        quiet_mask = valid_frames & (~moving_mask)

        cb_dict = cb_dicts[cell_idx] if cell_idx < len(cb_dicts) else None
        complex_mask = _build_complex_mask(speed.size, cb_dict)

        centers_complex = np.asarray(cb_dict.get("locs", []), dtype=int) if isinstance(cb_dict, dict) else np.array([], dtype=int)
        centers_complex = centers_complex[(centers_complex >= 0) & (centers_complex < speed.size)]

        ss_spikes = np.asarray(refined_ss[cell_idx], dtype=int) if cell_idx < len(refined_ss) else np.array([], dtype=int)
        ss_spikes = ss_spikes[(ss_spikes >= 0) & (ss_spikes < speed.size)]
        ss_spikes = ss_spikes[~complex_mask[ss_spikes]]
        ss_spikes = _enforce_min_gap(np.sort(ss_spikes), min_gap_frames)

        if ss_spikes.size > 0:
            expanded_simple_mask = np.zeros(speed.size, dtype=bool)
            for s in ss_spikes:
                lo = max(0, int(s) - simple_window)
                hi = min(speed.size, int(s) + simple_window + 1)
                expanded_simple_mask[lo:hi] = True
        else:
            expanded_simple_mask = np.zeros(speed.size, dtype=bool)

        # Exclusion around event centers for non-burst chunks.
        event_exclusion = np.zeros(speed.size, dtype=bool)
        half = chunk_frames // 2
        for c in np.concatenate([centers_complex, ss_spikes]) if (centers_complex.size or ss_spikes.size) else np.array([], dtype=int):
            lo = max(0, int(c) - half)
            hi = min(speed.size, int(c) + half + 1)
            event_exclusion[lo:hi] = True

        state_map = {
            "moving": moving_mask,
            "quiet": quiet_mask,
        }

        for state_key, state_mask in state_map.items():
            frq, chunks_complex = _event_psd_chunks(
                trace,
                centers_complex,
                state_mask,
                chunk_frames,
                frame_rate,
                nperseg,
                noverlap,
                config.pooled.min_chunk_valid_fraction,
            )
            if frq is not None and freqs_ref is None:
                freqs_ref = frq

            frq, chunks_simple = _event_psd_chunks(
                trace,
                ss_spikes,
                state_mask & expanded_simple_mask,
                chunk_frames,
                frame_rate,
                nperseg,
                noverlap,
                config.pooled.min_chunk_valid_fraction,
            )
            if frq is not None and freqs_ref is None:
                freqs_ref = frq

            non_burst_mask = state_mask & (~event_exclusion)
            frq, chunks_non_burst = _mask_to_psd_chunks(
                trace,
                non_burst_mask,
                chunk_frames,
                frame_rate,
                nperseg,
                noverlap,
            )
            if frq is not None and freqs_ref is None:
                freqs_ref = frq

            chunks_by_type = {
                "complex": chunks_complex,
                "simple": chunks_simple,
                "non_burst": chunks_non_burst,
            }

            for burst_type, chunks in chunks_by_type.items():
                if not chunks:
                    continue
                npz_key = cond_to_npz[(state_key, burst_type)]
                psd_rows[npz_key].append(np.nanmean(np.vstack(chunks), axis=0))
                cell_indices[npz_key].append(cell_idx)

    n_freq = int(len(freqs_ref)) if freqs_ref is not None else 0
    payload = {
        "freqs": np.asarray(freqs_ref if freqs_ref is not None else np.array([], dtype=float)),
        "cell_indices": cell_indices,
    }
    for npz_key, rows in psd_rows.items():
        payload[npz_key] = _stack_psd_rows(rows, n_freq)

    np.savez(out_path, **payload)
    return out_path


def _validate_psd_contract(animal_id: str, config: PipelineConfig) -> None:
    if not config.pooled.run_psd_sections:
        return
    npz_path = config.data_root / animal_id / f"psd_burstType_state_speed{int(config.pooled.psd_speed_threshold)}.npz"
    if not npz_path.exists():
        raise FileNotFoundError(f"Missing PSD artifact for {animal_id}: {npz_path}")

    npz = np.load(npz_path, allow_pickle=True)
    required_keys = {
        "freqs",
        "psd_moving_complex",
        "psd_moving_simple",
        "psd_quiet_complex",
        "psd_quiet_simple",
        "psd_moving_nonburst",
        "psd_quiet_nonburst",
        "cell_indices",
    }
    missing = sorted(required_keys.difference(npz.files))
    if missing:
        raise RuntimeError(f"PSD npz missing required keys for {animal_id}: {missing}")

    if config.pooled.cs_plc_only:
        cell_indices = npz["cell_indices"].item() if "cell_indices" in npz.files else None
        if not isinstance(cell_indices, dict):
            raise RuntimeError(f"PSD contract failure for {animal_id}: cell_indices must be a dict")


def _normalize_scalar_for_pickle(val: Any) -> Any:
    if isinstance(val, np.generic):
        return val.item()
    return val


def _build_and_save_animal_bundle(animal_id: str, config: PipelineConfig, fingerprint: str) -> Path:
    """Build canonical one-file cache bundle from legacy artifacts.

    We keep legacy files for notebook compatibility, and maintain this as the clean
    retrieval layer for downstream analyses.
    """
    import pandas as pd

    animal_dir = config.data_root / animal_id
    artifacts = _artifact_paths(animal_dir, config)

    df = pd.read_pickle(artifacts["pooled_stats"])
    with artifacts["spatial_analysis"].open("rb") as f:
        spatial_cells = pickle.load(f)
    with artifacts["pf_centered_trial_data"].open("rb") as f:
        pf_centered_data = pickle.load(f)

    theta_npz = np.load(artifacts["theta_amp_state"], allow_pickle=True)
    theta_run = np.asarray(theta_npz.get("theta_run", np.array([])), dtype=float)
    theta_rest = np.asarray(theta_npz.get("theta_rest", np.array([])), dtype=float)

    spatial_by_idx: dict[int, dict[str, Any]] = {}
    if isinstance(spatial_cells, list):
        for item in spatial_cells:
            if isinstance(item, dict) and "cell_idx" in item:
                spatial_by_idx[int(item["cell_idx"])] = item

    pf_by_idx: dict[int, dict[str, Any]] = {}
    if isinstance(pf_centered_data, list):
        for i, item in enumerate(pf_centered_data):
            if item is None or not isinstance(item, dict):
                continue
            idx = int(item.get("cell_idx", i))
            pf_by_idx[idx] = item
    elif isinstance(pf_centered_data, dict):
        for k, item in pf_centered_data.items():
            try:
                idx = int(k)
            except Exception:
                continue
            if isinstance(item, dict):
                pf_by_idx[idx] = item

    cell_records: list[CellCacheRecord] = []
    df_sorted = df.sort_values("cell_idx") if "cell_idx" in df.columns else df
    for _, row in df_sorted.iterrows():
        row_dict = {
            key: _normalize_scalar_for_pickle(val)
            for key, val in row.to_dict().items()
        }
        cell_idx = int(row_dict.get("cell_idx"))
        theta_state = None
        if cell_idx < len(theta_run) or cell_idx < len(theta_rest):
            run_val = float(theta_run[cell_idx]) if cell_idx < len(theta_run) else np.nan
            rest_val = float(theta_rest[cell_idx]) if cell_idx < len(theta_rest) else np.nan
            theta_state = {"run": run_val, "rest": rest_val}

        cell_records.append(
            CellCacheRecord(
                cell_idx=cell_idx,
                pooled=row_dict,
                spatial=spatial_by_idx.get(cell_idx),
                pf_centered=pf_by_idx.get(cell_idx),
                theta_amp_state=theta_state,
            )
        )

    bundle = AnimalCacheBundle(
        animal_id=animal_id,
        pipeline_version=PIPELINE_VERSION,
        fingerprint=fingerprint,
        generated_at=_utcnow_iso(),
        config={
            "analysis": asdict(config.analysis),
            "place_cell": asdict(config.place_cell),
            "traversal": asdict(config.traversal),
            "pooled": asdict(config.pooled),
        },
        cell_records=cell_records,
        artifact_paths={k: str(v) for k, v in artifacts.items()},
        notes={
            "n_cells": len(cell_records),
            "legacy_artifacts_kept_for_compatibility": True,
        },
    )

    out_path = _bundle_path(animal_dir)
    with out_path.open("wb") as f:
        pickle.dump(bundle, f)
    return out_path


def load_animal_cache_bundle(animal_id: str, config: PipelineConfig) -> AnimalCacheBundle:
    path = _bundle_path(config.data_root / animal_id)
    if not path.exists():
        raise FileNotFoundError(
            f"Bundle not found for {animal_id}: {path}. Run ensure_animal_cache first."
        )
    with path.open("rb") as f:
        bundle = pickle.load(f)
    if not isinstance(bundle, AnimalCacheBundle):
        raise TypeError(
            f"Unexpected bundle type at {path}: {type(bundle).__name__}. "
            "Rebuild cache to regenerate bundle."
        )
    return bundle


def get_cell_cache(animal_id: str, cell_idx: int, config: PipelineConfig) -> CellCacheRecord | None:
    bundle = load_animal_cache_bundle(animal_id, config)
    return bundle.get_cell(cell_idx)


def _filter_spike_list_with_bad_masks(
    spike_list: Any,
    bad_masks: np.ndarray,
    n_frames: int,
    n_cells: int,
) -> list[np.ndarray]:
    out: list[np.ndarray] = []
    for cell_idx in range(n_cells):
        src = []
        if isinstance(spike_list, (list, tuple)) and cell_idx < len(spike_list):
            src = spike_list[cell_idx]
        arr = np.asarray(src, dtype=int)
        if arr.size == 0:
            out.append(np.array([], dtype=int))
            continue
        arr = arr[(arr >= 0) & (arr < n_frames)]
        if bad_masks.shape[0] > cell_idx and arr.size > 0:
            arr = arr[~bad_masks[cell_idx][arr]]
        out.append(np.asarray(np.unique(arr), dtype=int))
    return out


def _prepare_native_analysis_context(
    merged: dict[str, Any],
    config: PipelineConfig,
) -> dict[str, Any]:
    x_neural = np.asarray(merged["x_neural"], dtype=float)
    y_neural = np.asarray(merged["y_neural"], dtype=float)
    hd_angles_neural = np.asarray(
        merged.get("hd_angles_neural", np.full_like(x_neural, np.nan)),
        dtype=float,
    )
    speed = np.asarray(merged["speed"], dtype=float)
    frame_rate = float(merged["frame_rate"])
    n_frames = int(len(x_neural))
    n_cells = int(len(merged["spikes"]))

    traces_raw = merged.get("traces_SNR_interpolated", merged.get("traces"))
    if traces_raw is None:
        raise KeyError("Missing traces in merged data.")
    traces = np.asarray(traces_raw, dtype=object)
    vms = np.asarray(merged.get("Vm_SNR_interpolated", traces_raw), dtype=object)

    bad_masks = _compute_bad_masks(
        merged,
        config.analysis.snr_threshold,
        config.analysis.min_good_minutes,
    )
    if bad_masks.shape != (n_cells, n_frames):
        raise RuntimeError(
            f"bad_masks shape mismatch: expected {(n_cells, n_frames)}, got {bad_masks.shape}"
        )

    good_minutes_by_cell = np.sum(~bad_masks, axis=1).astype(float) / frame_rate / 60.0
    eligible_cells = ~np.all(bad_masks, axis=1)

    all_spikes_raw = merged.get("all_spikes", merged["spikes"])
    refined_ss_raw = merged.get("refined_SS", [np.array([], dtype=int) for _ in range(n_cells)])
    all_cs_raw = merged.get("all_CS_spikes", [np.array([], dtype=int) for _ in range(n_cells)])

    all_spikes = _filter_spike_list_with_bad_masks(all_spikes_raw, bad_masks, n_frames, n_cells)
    refined_ss = _filter_spike_list_with_bad_masks(refined_ss_raw, bad_masks, n_frames, n_cells)
    all_cs_spikes = _filter_spike_list_with_bad_masks(all_cs_raw, bad_masks, n_frames, n_cells)
    spikes_for_analysis = list(all_spikes)

    complex_bursts_dicts = merged.get("complex_bursts_dicts", [dict() for _ in range(n_cells)])
    burst_metrics = merged.get("burst_metrics", [None for _ in range(n_cells)])
    plateaus_dicts = merged.get("plateaus_dicts", None)
    session_start_frames = merged.get("session_start_frames", [0])

    return {
        "x_neural": x_neural,
        "y_neural": y_neural,
        "hd_angles_neural": hd_angles_neural,
        "speed": speed,
        "frame_rate": frame_rate,
        "n_frames": n_frames,
        "n_cells": n_cells,
        "traces": traces,
        "vms": vms,
        "bad_masks": bad_masks,
        "good_minutes_by_cell": good_minutes_by_cell,
        "eligible_cells": np.asarray(eligible_cells, dtype=bool),
        "spikes": spikes_for_analysis,
        "all_spikes": all_spikes,
        "refined_ss": refined_ss,
        "all_cs_spikes": all_cs_spikes,
        "complex_bursts_dicts": complex_bursts_dicts,
        "burst_metrics": burst_metrics,
        "plateaus_dicts": plateaus_dicts,
        "session_start_frames": session_start_frames,
    }


def _run_place_cell_analysis_native(
    animal_id: str,
    config: PipelineConfig,
    ctx: dict[str, Any],
) -> list[dict[str, Any] | None]:
    n_cells = int(ctx["n_cells"])
    pc_output_all: list[dict[str, Any] | None] = [None] * n_cells

    p = config.place_cell
    a = config.analysis
    burst_metrics = ctx["burst_metrics"]
    if float(p.bin_size) <= 0:
        raise ValueError("place_cell.bin_size must be > 0.")

    for cell_idx in range(n_cells):
        if not bool(ctx["eligible_cells"][cell_idx]):
            continue
        out = core.analyze_place_cell_single_moving(
            ctx["x_neural"],
            ctx["y_neural"],
            ctx["spikes"],
            ctx["speed"],
            ctx["frame_rate"],
            cell_idx=cell_idx,
            axes=None,
            place_field_threshold=float(p.place_field_threshold),
            min_component_peak_ratio=float(p.min_component_peak_ratio),
            split_multi_peak_fields=bool(p.split_multi_peak_fields),
            split_secondary_peak_ratio=float(p.split_secondary_peak_ratio),
            split_secondary_peak_min_separation_cm=float(p.split_secondary_peak_min_separation_cm),
            min_field_bins=int(p.min_field_bins),
            speed_threshold=float(a.speed_threshold),
            kernel_size=int(a.kernel_size),
            filter_type="boxcar",
            min_duration_s=float(a.min_duration_s),
            merge_gap_s=float(a.merge_gap_s),
            plot_pf_contours=False,
            max_field_area_ratio=float(p.max_field_area_ratio),
            bad_timepoints=ctx["bad_masks"][cell_idx],
            num_shuffles=int(p.num_shuffles),
            random_seed=int(p.random_seed),
            plot_sub=False,
            traces=ctx["traces"],
            theta_freqs=tuple(a.theta_freqs),
            slow_freqs=float(a.slow_freqs),
            separate_spikes=True,
            refined_SS=ctx["refined_ss"],
            all_CS_spikes=ctx["all_cs_spikes"],
            complex_bursts_dicts=ctx["complex_bursts_dicts"],
            save_spike_shapes=True,
            ss_shape_pre_ms=10.0,
            ss_shape_post_ms=10.0,
            cb_shape_pre_ms=20.0,
            cb_shape_post_ms=80.0,
            save_burst_metrics=True,
            burst_metrics=burst_metrics,
            include_simple_bursts_metrics=False,
            save_spike_burst_rate_metrics=True,
            min_cb_bursts_per_condition=5,
            display_cell_num=cell_idx + 1,
            is_first_column=False,
            is_last_column=False,
            bin_size=float(p.bin_size),
            trim_sparse_top_row_for_analysis=bool(p.trim_sparse_top_row_for_analysis),
            trim_sparse_top_row_for_plotting=bool(p.trim_sparse_top_row_for_plotting),
            sparse_top_row_nonocc_frac_threshold=float(p.sparse_top_row_nonocc_frac_threshold),
            min_occupancy_s=float(p.min_occupancy_s),
            smooth_sigma=float(p.smooth_sigma),
            occ_smooth_sigma=float(p.occ_smooth_sigma),
            display_PF_SS_CS=True,
            min_peak_rate=float(p.min_peak_rate),
            min_pf_reliability=float(p.min_pf_reliability),
            min_pf_traversals=int(p.min_pf_traversals),
            pf_reliability_dilation_bins=int(p.pf_reliability_dilation_bins),
            pf_reliability_dilation_shape=str(p.pf_reliability_dilation_shape),
            ss_shape_min_separation_ms=float(p.ss_shape_min_separation_ms),
        )
        out["animal_id"] = animal_id
        out["cell_idx"] = cell_idx
        out["excluded_by_snr"] = False
        out["good_minutes"] = float(ctx["good_minutes_by_cell"][cell_idx])
        pc_output_all[cell_idx] = out

    n_kept = int(np.sum(ctx["eligible_cells"]))
    print(
        f"{animal_id}: SNR filter kept {n_kept}/{n_cells} cells "
        f"(threshold={config.analysis.snr_threshold}, min_good_minutes={config.analysis.min_good_minutes})."
    )
    return pc_output_all


def _save_theta_amp_state_npz(
    animal_dir: Path,
    config: PipelineConfig,
    ctx: dict[str, Any],
) -> Path:
    n_cells = int(ctx["n_cells"])
    theta_run = np.full(n_cells, np.nan, dtype=float)
    theta_rest = np.full(n_cells, np.nan, dtype=float)

    for cell_idx in range(n_cells):
        if not bool(ctx["eligible_cells"][cell_idx]):
            continue
        out_theta = core.compute_theta_amp_by_state(
            ctx["speed"],
            ctx["frame_rate"],
            trace=np.asarray(ctx["vms"][cell_idx], dtype=float),
            cell_idx=cell_idx,
            kernel_size=int(config.analysis.kernel_size),
            filter_type="boxcar",
            speed_threshold=float(config.analysis.speed_threshold),
            min_duration_s=float(config.analysis.min_duration_s),
            merge_gap_s=float(config.analysis.merge_gap_s),
            theta_freqs=tuple(config.analysis.theta_freqs),
            bad_timepoints=ctx["bad_masks"][cell_idx],
        )
        ta = out_theta.get("theta_amp", {})
        theta_run[cell_idx] = float(ta.get("run", np.nan))
        theta_rest[cell_idx] = float(ta.get("rest", np.nan))

    out_path = animal_dir / f"theta_amp_state_speed{int(config.analysis.speed_threshold)}.npz"
    np.savez(out_path, theta_run=theta_run, theta_rest=theta_rest)
    return out_path


def _save_spike_shapes_pf(
    animal_dir: Path,
    pc_output_all: list[dict[str, Any] | None],
) -> Path:
    place_cell_indices = [
        i for i, analysis in enumerate(pc_output_all)
        if isinstance(analysis, dict) and bool(analysis.get("is_place_cell", False))
    ]
    grand_stack = {
        "simple": {"run_in": [], "run_out": [], "rest_in": [], "rest_out": []},
        "complex": {"run_in": [], "run_out": [], "rest_in": [], "rest_out": []},
    }
    time_ms_simple = None
    time_ms_complex = None

    for cell_idx in place_cell_indices:
        analysis = pc_output_all[cell_idx]
        spike_shape_data = analysis.get("spike_shapes") if isinstance(analysis, dict) else None
        if not spike_shape_data:
            raise ValueError(
                "Missing `spike_shapes` in place-cell analysis output. "
                "Re-run analysis with save_spike_shapes=True."
            )
        if time_ms_simple is None:
            time_ms_simple = np.asarray(spike_shape_data["simple"]["time_ms"], dtype=float)
        if time_ms_complex is None:
            time_ms_complex = np.asarray(spike_shape_data["complex"]["time_ms"], dtype=float)
        for spike_type in ["simple", "complex"]:
            time_ms = time_ms_simple if spike_type == "simple" else time_ms_complex
            for cond in ["run_in", "run_out", "rest_in", "rest_out"]:
                waves = spike_shape_data[spike_type]["shapes"][cond]
                if len(waves) < 10:
                    grand_stack[spike_type][cond].append(
                        np.full_like(time_ms, np.nan, dtype=float)
                    )
                else:
                    grand_stack[spike_type][cond].append(
                        np.nanmean(np.vstack(waves), axis=0)
                    )

    if time_ms_simple is None:
        time_ms_simple = np.array([], dtype=float)
    if time_ms_complex is None:
        time_ms_complex = np.array([], dtype=float)

    out_path = animal_dir / "spike_shapes_PF.pkl"
    with out_path.open("wb") as f:
        pickle.dump(
            {
                "time_ms": {"simple": time_ms_simple, "complex": time_ms_complex},
                "grand_stack": grand_stack,
            },
            f,
        )
    return out_path


def _save_spike_burst_rates_pf(
    animal_dir: Path,
    config: PipelineConfig,
    ctx: dict[str, Any],
    pc_output_all: list[dict[str, Any] | None],
) -> Path:
    conditions = ["run_in", "run_out", "rest_in", "rest_out"]
    rate_metrics = {
        "simple_rate": {cond: [] for cond in conditions},
        "burst_rate": {cond: [] for cond in conditions},
        "burst_prob": {cond: [] for cond in conditions},
    }
    burst_counts = {cond: [] for cond in conditions}

    n_frames = int(ctx["n_frames"])
    x_neural = ctx["x_neural"]
    y_neural = ctx["y_neural"]
    speed = ctx["speed"]
    frame_rate = float(ctx["frame_rate"])

    for cell_idx, analysis in enumerate(pc_output_all):
        if not isinstance(analysis, dict) or not bool(analysis.get("is_place_cell", False)):
            continue
        if cell_idx >= len(ctx["complex_bursts_dicts"]):
            continue

        params = analysis.get("params", {})
        width_real = params.get("width_real", 35.5)
        height_real = params.get("height_real", 20.0)
        bin_size = params.get("bin_size", 1.5)
        bins = [
            np.arange(0, width_real + bin_size, bin_size),
            np.arange(0, height_real + bin_size, bin_size),
        ]
        place_field_mask = np.asarray(analysis.get("place_field_mask", []), dtype=bool)
        if place_field_mask.size == 0 or not np.any(place_field_mask):
            continue

        valid_frames = np.isfinite(x_neural) & np.isfinite(y_neural) & np.isfinite(speed)
        bad_mask = np.asarray(ctx["bad_masks"][cell_idx], dtype=bool)
        if bad_mask.shape[0] == n_frames:
            valid_frames &= ~bad_mask

        inside_pf = core.positions_in_place_field(x_neural, y_neural, bins, place_field_mask)

        moving_mask = np.zeros(n_frames, dtype=bool)
        moving_idx = analysis.get("moving_indices", [])
        if moving_idx is not None and len(moving_idx) > 0:
            moving_mask[np.asarray(moving_idx, dtype=int)] = True
        else:
            moving_mask = (speed > float(config.analysis.speed_threshold)) & valid_frames
        moving_mask &= valid_frames

        simple_events = np.asarray(ctx["refined_ss"][cell_idx], dtype=int)
        simple_events = simple_events[(simple_events >= 0) & (simple_events < n_frames)]

        bursts = ctx["complex_bursts_dicts"][cell_idx] if cell_idx < len(ctx["complex_bursts_dicts"]) else {}
        starts = np.asarray(bursts.get("starts", []), dtype=int)
        ends = np.asarray(bursts.get("ends", []), dtype=int)
        cs_spikes = np.asarray(ctx["all_cs_spikes"][cell_idx], dtype=int)
        cs_spikes = cs_spikes[(cs_spikes >= 0) & (cs_spikes < n_frames)]
        burst_events = []
        for start_idx, end_idx in zip(starts, ends):
            in_burst = cs_spikes[(cs_spikes >= start_idx) & (cs_spikes <= end_idx)]
            if in_burst.size == 0:
                continue
            burst_events.append(int(in_burst[0]))
        burst_events = np.asarray(burst_events, dtype=int)

        cond_masks = {
            "run_in": moving_mask & inside_pf & valid_frames,
            "run_out": moving_mask & (~inside_pf) & valid_frames,
            "rest_in": (~moving_mask) & inside_pf & valid_frames,
            "rest_out": (~moving_mask) & (~inside_pf) & valid_frames,
        }

        for cond in conditions:
            mask = cond_masks[cond]
            time_s = float(np.sum(mask) / frame_rate)
            if time_s <= 0:
                burst_counts[cond].append(0)
                rate_metrics["simple_rate"][cond].append(np.nan)
                rate_metrics["burst_rate"][cond].append(np.nan)
                rate_metrics["burst_prob"][cond].append(np.nan)
                continue

            simple_count = int(np.sum(mask[simple_events])) if simple_events.size > 0 else 0
            burst_count = int(np.sum(mask[burst_events])) if burst_events.size > 0 else 0
            total_events = simple_count + burst_count

            burst_counts[cond].append(burst_count)
            rate_metrics["simple_rate"][cond].append(simple_count / time_s)
            rate_metrics["burst_rate"][cond].append(burst_count / time_s)
            rate_metrics["burst_prob"][cond].append(
                (burst_count / total_events) if total_events > 0 else np.nan
            )

    out_path = animal_dir / "spike_burst_rates_PF.pkl"
    with out_path.open("wb") as f:
        pickle.dump(
            {
                "rate_metrics": rate_metrics,
                "burst_counts": burst_counts,
                "conditions": conditions,
                "min_cb_bursts_per_condition": 5,
            },
            f,
        )
    return out_path


def _save_burst_metrics_pf(
    animal_dir: Path,
    pc_output_all: list[dict[str, Any] | None],
) -> Path:
    include_simple_bursts = False
    conditions = ["run_in", "run_out", "rest_in", "rest_out"]
    min_bursts_per_condition = 5
    metric_specs = [
        ("n_spikes", "Spks./burst"),
        ("peak_amp", "Peak amp"),
        ("duration_ms", "Duration (ms)"),
        ("auc", "AUC"),
    ]
    metric_data = {
        "complex": {metric: {cond: [] for cond in conditions} for metric, _ in metric_specs},
        "simple": {metric: {cond: [] for cond in conditions} for metric, _ in metric_specs},
    }
    cond_counts = {
        "complex": {cond: [] for cond in conditions},
        "simple": {cond: [] for cond in conditions},
    }

    for analysis in pc_output_all:
        if not isinstance(analysis, dict) or not bool(analysis.get("is_place_cell", False)):
            continue
        bursts_by_cond = analysis.get("burst_metrics")
        if not isinstance(bursts_by_cond, dict):
            continue

        for burst_type in ["complex", "simple"]:
            if burst_type == "simple" and (not include_simple_bursts):
                continue
            cond_map = bursts_by_cond.get(burst_type, {}) if isinstance(bursts_by_cond, dict) else {}
            for cond in conditions:
                bursts = cond_map.get(cond, []) if isinstance(cond_map, dict) else []
                if not isinstance(bursts, list):
                    bursts = []
                cond_counts[burst_type][cond].append(len(bursts))
                for metric, _ in metric_specs:
                    if len(bursts) < min_bursts_per_condition:
                        metric_data[burst_type][metric][cond].append(np.nan)
                        continue
                    vals = np.asarray([b.get(metric, np.nan) for b in bursts], dtype=float)
                    metric_data[burst_type][metric][cond].append(float(np.nanmean(vals)))

    out_path = animal_dir / "burst_metrics_PF.pkl"
    with out_path.open("wb") as f:
        pickle.dump(
            {
                "metric_data": metric_data,
                "cond_counts": cond_counts,
                "conditions": conditions,
                "metric_specs": metric_specs,
                "min_bursts_per_condition": min_bursts_per_condition,
                "include_simple_bursts": include_simple_bursts,
            },
            f,
        )
    return out_path


def _collect_all_cells_stats(
    config: PipelineConfig,
    ctx: dict[str, Any],
    pc_output_all: list[dict[str, Any] | None],
) -> list[dict[str, Any]]:
    n_frames = int(ctx["n_frames"])
    speed_arr = np.asarray(ctx["speed"], dtype=float)
    x_neural = np.asarray(ctx["x_neural"], dtype=float)
    y_neural = np.asarray(ctx["y_neural"], dtype=float)
    frame_rate = float(ctx["frame_rate"])

    speed_clean = speed_arr.copy()
    speed_clean[speed_clean > 50] = np.nan
    valid_frames_global = np.isfinite(speed_clean) & np.isfinite(x_neural) & np.isfinite(y_neural)

    bin_size = 1.5
    bins = [
        np.arange(0, 35.5 + bin_size, bin_size),
        np.arange(0, 20.0 + bin_size, bin_size),
    ]

    all_cells_stats: list[dict[str, Any]] = []
    for cell_idx in range(int(ctx["n_cells"])):
        if not bool(ctx["eligible_cells"][cell_idx]):
            continue

        stats_row: dict[str, Any] = {"cell_idx": cell_idx}
        bad_mask = np.asarray(ctx["bad_masks"][cell_idx], dtype=bool)
        if bad_mask.shape[0] != n_frames:
            bad_mask = np.zeros(n_frames, dtype=bool)
        valid_frames_cell = valid_frames_global & (~bad_mask)

        # Prefer cell-specific moving indices already generated during place-cell analysis
        # with bad_timepoints applied.
        analysis = pc_output_all[cell_idx]
        moving_mask_cell = np.zeros(n_frames, dtype=bool)
        if isinstance(analysis, dict):
            moving_idx_cell = analysis.get("moving_indices", [])
            if moving_idx_cell is not None and len(moving_idx_cell) > 0:
                moving_mask_cell[np.asarray(moving_idx_cell, dtype=int)] = True
        if not np.any(moving_mask_cell):
            speed_for_epochs = speed_clean.copy()
            speed_for_epochs[~valid_frames_cell] = np.nan
            _, _, moving_idx_cell = core._compute_moving_epochs(
                speed_for_epochs,
                frame_rate,
                kernel_size=int(config.analysis.kernel_size),
                filter_type="boxcar",
                speed_threshold=float(config.analysis.speed_threshold),
                min_duration_s=float(config.analysis.min_duration_s),
                merge_gap_s=float(config.analysis.merge_gap_s),
            )
            if len(moving_idx_cell) > 0:
                moving_mask_cell[np.asarray(moving_idx_cell, dtype=int)] = True
        moving_mask_cell &= valid_frames_cell
        quiet_mask_cell = valid_frames_cell & (~moving_mask_cell)
        loco_time_cell = float(np.sum(moving_mask_cell) / frame_rate)
        quiet_time_cell = float(np.sum(quiet_mask_cell) / frame_rate)

        all_spk = np.asarray(ctx["spikes"][cell_idx], dtype=int)
        ss_spk = np.asarray(ctx["refined_ss"][cell_idx], dtype=int)
        cs_spk = np.asarray(ctx["all_cs_spikes"][cell_idx], dtype=int)

        for name, spk in [("all", all_spk), ("ss", ss_spk), ("cs", cs_spk)]:
            n_loco = int(np.sum(moving_mask_cell[spk])) if len(spk) > 0 else 0
            n_quiet = int(np.sum(quiet_mask_cell[spk])) if len(spk) > 0 else 0
            stats_row[f"{name}_rate_loco"] = n_loco / loco_time_cell if loco_time_cell > 0 else np.nan
            stats_row[f"{name}_rate_quiet"] = n_quiet / quiet_time_cell if quiet_time_cell > 0 else np.nan

        stats_row["is_place_cell"] = bool(analysis["is_place_cell"]) if isinstance(analysis, dict) else False
        stats_row["si"] = analysis.get("si", np.nan) if isinstance(analysis, dict) else np.nan
        stats_row["p_value"] = analysis.get("p_value", np.nan) if isinstance(analysis, dict) else np.nan

        if isinstance(analysis, dict):
            stats_row["is_place_cell_ss"] = analysis.get("is_place_cell_ss", False)
            stats_row["is_place_cell_cs"] = analysis.get("is_place_cell_cs", False)
            stats_row["ss_si"] = analysis.get("ss_si", np.nan)
            stats_row["ss_p_value"] = analysis.get("ss_p_value", np.nan)
            stats_row["cs_si"] = analysis.get("cs_si", np.nan)
            stats_row["cs_p_value"] = analysis.get("cs_p_value", np.nan)
            stats_row["theta_corr_all"] = analysis.get("theta_corr_all", np.nan)
            stats_row["theta_corr_ss"] = analysis.get("theta_corr_ss", np.nan)
            stats_row["theta_corr_cs"] = analysis.get("theta_corr_cs", np.nan)
            stats_row["slow_corr_all"] = analysis.get("slow_corr_all", np.nan)
            stats_row["slow_corr_ss"] = analysis.get("slow_corr_ss", np.nan)
            stats_row["slow_corr_cs"] = analysis.get("slow_corr_cs", np.nan)
        else:
            stats_row["is_place_cell_ss"] = False
            stats_row["is_place_cell_cs"] = False
            stats_row["ss_si"] = np.nan
            stats_row["ss_p_value"] = np.nan
            stats_row["cs_si"] = np.nan
            stats_row["cs_p_value"] = np.nan
            stats_row["theta_corr_all"] = np.nan
            stats_row["theta_corr_ss"] = np.nan
            stats_row["theta_corr_cs"] = np.nan
            stats_row["slow_corr_all"] = np.nan
            stats_row["slow_corr_ss"] = np.nan
            stats_row["slow_corr_cs"] = np.nan

        if not isinstance(analysis, dict) or not bool(analysis.get("is_place_cell", False)):
            for prefix in ["", "_ss", "_cs"]:
                for key in [
                    f"peak_rate{prefix}",
                    f"si_bits_per_spike{prefix}",
                    f"n_place_fields{prefix}",
                    f"total_pf_size_cm2{prefix}",
                ]:
                    stats_row[key.replace("_all", "")] = np.nan
                stats_row[f"place_field_sizes_cm2{prefix}"] = []
            stats_row["peak_rate_all"] = np.nan
            stats_row["peak_pct_in_ss"] = np.nan
            stats_row["peak_pct_in_cs"] = np.nan
            for spike_type in ["all", "ss", "cs"]:
                for k in ["loco_in", "loco_out", "loco_ratio", "quiet_in", "quiet_out", "quiet_ratio"]:
                    stats_row[f"{spike_type}_inout_{k}"] = np.nan
            for k in [
                "theta_loco_in",
                "theta_loco_out",
                "theta_quiet_in",
                "theta_quiet_out",
                "slow_loco_in",
                "slow_loco_out",
                "slow_quiet_in",
                "slow_quiet_out",
            ]:
                stats_row[k] = np.nan
            all_cells_stats.append(stats_row)
            continue

        pf_mask = np.asarray(analysis["place_field_mask"], dtype=bool)
        peak_all_raw = analysis.get("peak_rate", np.nan)
        stats_row["peak_rate_all"] = peak_all_raw if np.isfinite(peak_all_raw) else 0.0
        stats_row["peak_rate_ss"] = analysis.get("ss_peak_rate", 0.0)
        stats_row["peak_rate_cs"] = analysis.get("cs_peak_rate", 0.0)

        for name, rmap_key in [("ss", "ss_rate_map"), ("cs", "cs_rate_map")]:
            rmap = analysis.get(rmap_key)
            if rmap is not None and np.any(pf_mask):
                peak_in = np.nanmax(rmap[pf_mask]) if np.any(np.isfinite(rmap[pf_mask])) else np.nan
                peak_all = np.nanmax(rmap) if np.any(np.isfinite(rmap)) else np.nan
                stats_row[f"peak_pct_in_{name}"] = (peak_in / peak_all * 100) if np.isfinite(peak_all) and peak_all > 0 else np.nan
            else:
                stats_row[f"peak_pct_in_{name}"] = np.nan

        stats_row["si_bits_per_spike"] = analysis.get("si_bits_per_spike", np.nan)
        stats_row["si_bits_per_spike_ss"] = analysis.get("si_bits_per_spike_ss", np.nan)
        stats_row["si_bits_per_spike_cs"] = analysis.get("si_bits_per_spike_cs", np.nan)
        stats_row["n_place_fields"] = analysis.get("n_place_fields", 0)
        pf_sizes = analysis.get("pf_sizes", [0])
        stats_row["place_field_sizes_cm2"] = pf_sizes if pf_sizes else [0]
        stats_row["total_pf_size_cm2"] = analysis.get("field_area", 0.0)
        stats_row["n_place_fields_ss"] = analysis.get("n_ss_place_fields", 0)
        ss_pf_sizes = analysis.get("ss_pf_sizes", [0])
        stats_row["place_field_sizes_cm2_ss"] = ss_pf_sizes if ss_pf_sizes else [0]
        stats_row["total_pf_size_cm2_ss"] = analysis.get("ss_field_area", 0.0)
        stats_row["n_place_fields_cs"] = analysis.get("n_cs_place_fields", 0)
        cs_pf_sizes = analysis.get("cs_pf_sizes", [0])
        stats_row["place_field_sizes_cm2_cs"] = cs_pf_sizes if cs_pf_sizes else [0]
        stats_row["total_pf_size_cm2_cs"] = analysis.get("cs_field_area", 0.0)

        for name, spk in [("all", all_spk), ("ss", ss_spk), ("cs", cs_spk)]:
            inout = core.compute_in_out_ratio(
                spk,
                x_neural,
                y_neural,
                pf_mask,
                bins,
                moving_mask_cell,
                quiet_mask_cell,
                frame_rate,
            )
            for k, v in inout.items():
                stats_row[f"{name}_inout_{k}"] = v

        theta_slow = core.compute_theta_slow_in_out(
            np.asarray(ctx["vms"][cell_idx], dtype=float),
            x_neural,
            y_neural,
            pf_mask,
            bins,
            moving_mask_cell,
            quiet_mask_cell,
            frame_rate,
            tuple(config.analysis.theta_freqs),
            float(config.analysis.slow_freqs),
        )
        stats_row.update(theta_slow)
        all_cells_stats.append(stats_row)

    return all_cells_stats


def _save_pooled_stats_artifact(animal_dir: Path, all_cells_stats: list[dict[str, Any]]) -> Path:
    import pandas as pd

    df_all = pd.DataFrame(all_cells_stats)
    out_pkl = animal_dir / "pooled_stats.pkl"
    out_csv = animal_dir / "pooled_stats.csv"
    df_all.to_pickle(out_pkl)
    if "place_field_sizes_cm2" in df_all.columns:
        save_df = df_all.drop(columns=["place_field_sizes_cm2"])
    else:
        save_df = df_all.copy()
    save_df.to_csv(out_csv, index=False)
    return out_pkl


def _save_spatial_analysis_artifact(
    animal_id: str,
    animal_dir: Path,
    ctx: dict[str, Any],
    pc_output_all: list[dict[str, Any] | None],
) -> Path:
    spatial_results_for_pooling = []
    n_frames_total = int(ctx["n_frames"])
    pos_nan_mask_global = (
        (~np.isfinite(np.asarray(ctx["x_neural"], dtype=float)))
        | (~np.isfinite(np.asarray(ctx["y_neural"], dtype=float)))
        | (~np.isfinite(np.asarray(ctx["speed"], dtype=float)))
    )

    for cell_idx, analysis in enumerate(pc_output_all):
        if not bool(ctx["eligible_cells"][cell_idx]):
            continue
        if not isinstance(analysis, dict):
            continue

        moving_idx = np.asarray(analysis.get("moving_indices", []), dtype=int)
        x_traj = np.asarray(analysis.get("x_traj", np.array([], dtype=float)), dtype=float)
        y_traj = np.asarray(analysis.get("y_traj", np.array([], dtype=float)), dtype=float)

        ss_spikes_x, ss_spikes_y = _get_spike_positions_on_traj(
            ctx["refined_ss"][cell_idx] if cell_idx < len(ctx["refined_ss"]) else None,
            moving_idx,
            x_traj,
            y_traj,
            n_frames_total,
        )
        cs_spikes_x, cs_spikes_y = _get_spike_positions_on_traj(
            ctx["all_cs_spikes"][cell_idx] if cell_idx < len(ctx["all_cs_spikes"]) else None,
            moving_idx,
            x_traj,
            y_traj,
            n_frames_total,
        )
        bad_mask = np.asarray(ctx["bad_masks"][cell_idx], dtype=bool)
        if bad_mask.shape[0] != n_frames_total:
            bad_mask = np.zeros(n_frames_total, dtype=bool)
        removed_total = int(np.sum(bad_mask))
        removed_pos_nan = int(np.sum(bad_mask & pos_nan_mask_global))
        removed_snr_only = int(np.sum(bad_mask & (~pos_nan_mask_global)))
        kept_total = int(n_frames_total - removed_total)
        pct_removed_total = (100.0 * removed_total / n_frames_total) if n_frames_total > 0 else np.nan
        pct_removed_snr_only = (100.0 * removed_snr_only / n_frames_total) if n_frames_total > 0 else np.nan

        cell_result = {
            "animal_id": animal_id,
            "cell_idx": cell_idx,
            "is_place_cell": bool(analysis.get("is_place_cell", False)),
            "is_place_cell_ss": bool(analysis.get("is_place_cell_ss", False)),
            "is_place_cell_cs": bool(analysis.get("is_place_cell_cs", False)),
            "si": analysis.get("si", np.nan),
            "p_value": analysis.get("p_value", np.nan),
            "ss_si": analysis.get("ss_si", np.nan),
            "ss_p_value": analysis.get("ss_p_value", np.nan),
            "cs_si": analysis.get("cs_si", np.nan),
            "cs_p_value": analysis.get("cs_p_value", np.nan),
            "peak_rate": analysis.get("peak_rate", np.nan),
            "ss_peak_rate": analysis.get("ss_peak_rate", np.nan),
            "cs_peak_rate": analysis.get("cs_peak_rate", np.nan),
            "rate_map": analysis.get("rate_map", None),
            "ss_rate_map": analysis.get("ss_rate_map", None),
            "cs_rate_map": analysis.get("cs_rate_map", None),
            "ss_norm_map": analysis.get("ss_norm_map", None),
            "cs_norm_map": analysis.get("cs_norm_map", None),
            "occupancy": analysis.get("occupancy", None),
            "place_field_mask": analysis.get("place_field_mask", None),
            "ss_place_field_mask": analysis.get("ss_place_field_mask", None),
            "cs_place_field_mask": analysis.get("cs_place_field_mask", None),
            "place_field_components": analysis.get("place_field_components", []),
            "pf_sizes": analysis.get("pf_sizes", [0]),
            "ss_pf_sizes": analysis.get("ss_pf_sizes", [0]),
            "cs_pf_sizes": analysis.get("cs_pf_sizes", [0]),
            "n_place_fields": analysis.get("n_place_fields", 0),
            "n_ss_place_fields": analysis.get("n_ss_place_fields", 0),
            "n_cs_place_fields": analysis.get("n_cs_place_fields", 0),
            "field_area": analysis.get("field_area", 0.0),
            "ss_field_area": analysis.get("ss_field_area", 0.0),
            "cs_field_area": analysis.get("cs_field_area", 0.0),
            "si_bits_per_spike": analysis.get("si_bits_per_spike", np.nan),
            "si_bits_per_spike_ss": analysis.get("si_bits_per_spike_ss", np.nan),
            "si_bits_per_spike_cs": analysis.get("si_bits_per_spike_cs", np.nan),
            "x_traj": x_traj,
            "y_traj": y_traj,
            "spikes_x": analysis.get("spikes_x", np.array([])),
            "spikes_y": analysis.get("spikes_y", np.array([])),
            "ss_spikes_x": ss_spikes_x,
            "ss_spikes_y": ss_spikes_y,
            "cs_spikes_x": cs_spikes_x,
            "cs_spikes_y": cs_spikes_y,
            "theta_corr_all": analysis.get("theta_corr_all", np.nan),
            "theta_corr_ss": analysis.get("theta_corr_ss", np.nan),
            "theta_corr_cs": analysis.get("theta_corr_cs", np.nan),
            "slow_corr_all": analysis.get("slow_corr_all", np.nan),
            "slow_corr_ss": analysis.get("slow_corr_ss", np.nan),
            "slow_corr_cs": analysis.get("slow_corr_cs", np.nan),
            "theta_map": analysis.get("theta_map", None),
            "slow_map": analysis.get("slow_map", None),
            "spike_shapes": analysis.get("spike_shapes"),
            "burst_metrics": analysis.get("burst_metrics"),
            "spike_burst_rate_metrics": analysis.get("spike_burst_rate_metrics"),
            "params": analysis.get("params", {}),
            "n_frames_total": n_frames_total,
            "n_frames_kept_total": kept_total,
            "n_removed_frames_total": removed_total,
            "n_removed_frames_snr_only": removed_snr_only,
            "n_removed_frames_pos_nan": removed_pos_nan,
            "pct_removed_frames_total": pct_removed_total,
            "pct_removed_frames_snr_only": pct_removed_snr_only,
        }
        spatial_results_for_pooling.append(cell_result)

    out_path = animal_dir / "spatial_analysis_full.pkl"
    with out_path.open("wb") as f:
        pickle.dump(spatial_results_for_pooling, f)
    return out_path


def _save_pf_centered_trial_data_artifact(
    animal_dir: Path,
    config: PipelineConfig,
    ctx: dict[str, Any],
    pc_output_all: list[dict[str, Any] | None],
) -> Path:
    pf_centered_data: list[dict[str, Any] | None] = [None] * len(pc_output_all)
    for cell_idx, analysis in enumerate(pc_output_all):
        if not bool(ctx["eligible_cells"][cell_idx]):
            continue
        if not isinstance(analysis, dict) or not bool(analysis.get("is_place_cell", False)):
            continue
        result = compute_pf_centered_trial_data(
            cell_idx=cell_idx,
            PC_output_all=pc_output_all,
            traces=ctx["traces"],
            vms=ctx["vms"],
            x_neural=ctx["x_neural"],
            y_neural=ctx["y_neural"],
            speed=ctx["speed"],
            spikes=ctx["spikes"],
            all_spikes=ctx["all_spikes"],
            refined_SS=ctx["refined_ss"],
            all_CS_spikes=ctx["all_cs_spikes"],
            frame_rate=ctx["frame_rate"],
            pf_center_window_sec=float(config.traversal.pf_center_window_sec),
            theta_freqs=tuple(config.analysis.theta_freqs),
            slow_freqs=float(config.analysis.slow_freqs),
            speed_threshold=float(config.analysis.speed_threshold),
            min_duration_ms=float(config.traversal.min_duration_ms),
            place_field_threshold=float(config.place_cell.place_field_threshold),
            min_distance_cm=float(config.traversal.min_distance_cm),
            clear_traversal=bool(config.traversal.clear_traversal),
            session_start_frames=ctx["session_start_frames"],
            session_indices=tuple(config.traversal.session_indices),
            bad_masks=ctx["bad_masks"],
            center_by_pf_position=bool(config.traversal.center_by_pf_position),
            firing_rate_bin_ms=float(config.traversal.firing_rate_bin_ms),
            firing_rate_smooth_ms=float(config.traversal.firing_rate_smooth_ms),
            min_traversals=int(config.traversal.min_traversals),
            mask_non_traversal_pf=bool(config.traversal.mask_non_traversal_pf),
            max_pf_distance_cm=config.traversal.max_pf_distance_cm,
            pf_component_selection=str(config.traversal.pf_component_selection),
            complex_bursts_dicts=ctx["complex_bursts_dicts"],
            plateaus_dicts=ctx["plateaus_dicts"],
            plateau_min_duration_ms=float(config.traversal.plateau_min_duration_ms),
        )
        pf_centered_data[cell_idx] = result

    frame_rate = float(ctx["frame_rate"])
    window_sec = float(config.traversal.pf_center_window_sec)
    time_rel = np.arange(
        -int(round(window_sec * frame_rate)),
        int(round(window_sec * frame_rate)) + 1,
    ) / frame_rate
    payload = {
        "pf_centered_data": pf_centered_data,
        "time_rel": time_rel,
        "center_by_pf_position": bool(config.traversal.center_by_pf_position),
        "theta_freqs": tuple(config.analysis.theta_freqs),
        "slow_freqs": float(config.analysis.slow_freqs),
        "pf_center_window_sec": window_sec,
        "frame_rate": frame_rate,
        "min_traversals": int(config.traversal.min_traversals),
    }
    out_path = animal_dir / "pf_centered_trial_data.pkl"
    with out_path.open("wb") as f:
        pickle.dump(payload, f)
    return out_path


def _recompute_animal_cache(animal_id: str, config: PipelineConfig) -> None:
    animal_dir = config.data_root / animal_id
    animal_dir.mkdir(parents=True, exist_ok=True)
    merged = _load_merged_data(animal_dir)
    ctx = _prepare_native_analysis_context(merged, config)
    pc_output_all = _run_place_cell_analysis_native(animal_id, config, ctx)

    _save_theta_amp_state_npz(animal_dir, config, ctx)
    _save_spike_shapes_pf(animal_dir, pc_output_all)
    _save_spike_burst_rates_pf(animal_dir, config, ctx, pc_output_all)
    _save_burst_metrics_pf(animal_dir, pc_output_all)

    all_cells_stats = _collect_all_cells_stats(config, ctx, pc_output_all)
    _save_pooled_stats_artifact(animal_dir, all_cells_stats)
    _save_spatial_analysis_artifact(animal_id, animal_dir, ctx, pc_output_all)
    _save_pf_centered_trial_data_artifact(animal_dir, config, ctx, pc_output_all)

    # Generate/refresh PSD burst-type artifact with required cell_indices contract.
    generate_psd_burst_type_state_npz(animal_id, config)


def ensure_animal_cache(animal_id: str, config: PipelineConfig, force: bool = False) -> AnimalCacheStatus:
    animal_dir = config.data_root / animal_id
    manifest = _load_manifest(config.manifest_path)
    force_recompute = bool(force or config.cache.force_recompute)
    if force_recompute and not config.cache.validate_only:
        removed = _purge_animal_cache_artifacts(animal_dir)
        if removed:
            print(f"{animal_id}: purged {len(removed)} cached artifact files (force_recompute=True).")
        if animal_id in manifest.get("animals", {}):
            manifest["animals"].pop(animal_id, None)
            _save_manifest(config.manifest_path, manifest)

    artifact_paths = _artifact_paths(animal_dir, config)
    missing = sorted([key for key, p in artifact_paths.items() if not p.exists()])
    fingerprint = _config_fingerprint(config, animal_id)
    prev = manifest.get("animals", {}).get(animal_id, {})
    prev_fp = prev.get("fingerprint")

    reasons: list[str] = []
    if missing:
        reasons.append("missing_artifacts")
    if prev_fp != fingerprint:
        reasons.append("fingerprint_mismatch")
    if force_recompute:
        reasons.append("force_recompute")

    needs_recompute = len(reasons) > 0
    if config.cache.validate_only and needs_recompute:
        return AnimalCacheStatus(
            animal_id=animal_id,
            action="needs_recompute",
            reasons=reasons,
            missing_artifacts=missing,
            fingerprint=fingerprint,
        )

    if needs_recompute:
        _recompute_animal_cache(animal_id, config)
        # Validate artifact contract after recompute.
        artifact_paths = _artifact_paths(animal_dir, config)
        missing_after = sorted([key for key, p in artifact_paths.items() if not p.exists()])
        if missing_after:
            raise RuntimeError(
                f"Recompute completed but required artifacts are still missing for {animal_id}: {missing_after}"
            )
        _validate_psd_contract(animal_id, config)
        bundle_path = _build_and_save_animal_bundle(animal_id, config, fingerprint)

        manifest.setdefault("animals", {})[animal_id] = {
            "fingerprint": fingerprint,
            "source_identity": _source_identity(animal_dir),
            "updated_at": _utcnow_iso(),
            "artifact_mtime_ns": {
                key: int(path.stat().st_mtime_ns) for key, path in artifact_paths.items()
            },
            "bundle_path": str(bundle_path),
            "bundle_mtime_ns": int(bundle_path.stat().st_mtime_ns),
        }
        _save_manifest(config.manifest_path, manifest)
        return AnimalCacheStatus(
            animal_id=animal_id,
            action="recomputed",
            reasons=reasons,
            missing_artifacts=missing,
            fingerprint=fingerprint,
        )

    # Up-to-date cache. Ensure manifest has current timestamp/source metadata.
    bundle_path = _build_and_save_animal_bundle(animal_id, config, fingerprint)
    manifest.setdefault("animals", {})[animal_id] = {
        "fingerprint": fingerprint,
        "source_identity": _source_identity(animal_dir),
        "updated_at": _utcnow_iso(),
        "artifact_mtime_ns": {
            key: int(path.stat().st_mtime_ns) for key, path in artifact_paths.items()
        },
        "bundle_path": str(bundle_path),
        "bundle_mtime_ns": int(bundle_path.stat().st_mtime_ns),
    }
    _save_manifest(config.manifest_path, manifest)
    return AnimalCacheStatus(
        animal_id=animal_id,
        action="reused",
        reasons=[],
        missing_artifacts=[],
        fingerprint=fingerprint,
    )


def ensure_cache_for_all_animals(config: PipelineConfig, force: bool = False) -> list[AnimalCacheStatus]:
    statuses: list[AnimalCacheStatus] = []
    for animal_id in config.animals:
        status = ensure_animal_cache(animal_id, config, force=force)
        statuses.append(status)
    return statuses


def _patch_pooled_notebook(
    nb: nbformat.NotebookNode,
    config: PipelineConfig,
) -> nbformat.NotebookNode:
    patched = nbformat.from_dict(nb)

    setup_cell = patched.cells[1]
    src = setup_cell.source
    src = re.sub(
        r"data_folder\s*=\s*['\"].*?['\"]",
        f"data_folder = {str(config.data_root)!r}",
        src,
        count=1,
    )
    src = re.sub(
        r"figure_save_folder\s*=\s*['\"].*?['\"]",
        f"figure_save_folder = {str(config.figures_root / 'CKII_pooled')!r}",
        src,
        count=1,
    )
    src = re.sub(
        r"CB_NUM_THRESHOLD\s*=\s*\d+",
        f"CB_NUM_THRESHOLD = {int(config.pooled.cb_num_threshold)}",
        src,
        count=1,
    )
    src = re.sub(
        r"CS_PEAK_RATE_THRESHOLD\s*=\s*[0-9]*\.?[0-9]+",
        f"CS_PEAK_RATE_THRESHOLD = {float(config.pooled.cs_peak_rate_threshold)}",
        src,
        count=1,
    )
    src = _replace_list_assignment(src, "ckii_folders", list(config.animals))

    src = src.replace(
        "merged_path = os.path.join(data_folder, folder, 'merged_aligned_data_CS.pkl')",
        "merged_path = os.path.join(data_folder, folder, 'merged_aligned_data_CS.pkl')\n"
        "        if not os.path.exists(merged_path):\n"
        "            merged_path = os.path.join(data_folder, folder, 'merged_aligned_data.pkl')",
    )
    setup_cell.source = src

    # PSD setup cell patch.
    psd_cfg_idx = 67
    if len(patched.cells) > psd_cfg_idx and patched.cells[psd_cfg_idx].cell_type == "code":
        src = patched.cells[psd_cfg_idx].source
        src = re.sub(
            r"cs_plc_only\s*=\s*(True|False)",
            f"cs_plc_only = {bool(config.pooled.cs_plc_only)}",
            src,
            count=1,
        )
        src = re.sub(
            r"speed_threshold\s*=\s*\d+",
            f"speed_threshold = {int(config.pooled.psd_speed_threshold)}",
            src,
            count=1,
        )
        src = re.sub(
            r"max_freq\s*=\s*\d+",
            f"max_freq = {int(config.pooled.max_freq)}",
            src,
            count=1,
        )
        src = re.sub(
            r"normalize_psd\s*=\s*(True|False)",
            f"normalize_psd = {bool(config.pooled.normalize_psd)}",
            src,
            count=1,
        )
        src = re.sub(
            r"norm_freq_range\s*=\s*\([^\)]*\)",
            f"norm_freq_range = ({float(config.pooled.norm_freq_range[0])}, {float(config.pooled.norm_freq_range[1])})",
            src,
            count=1,
        )
        patched.cells[psd_cfg_idx].source = src

    if not config.pooled.run_psd_sections:
        for idx in [67, 68, 69, 70, 71]:
            if idx < len(patched.cells) and patched.cells[idx].cell_type == "code":
                patched.cells[idx].source = "print('PSD sections skipped by run_psd_sections=False')"

    return patched


def _build_save_filter_cell(allowed_patterns: list[str]) -> nbformat.NotebookNode:
    pattern_literal = repr(list(allowed_patterns))
    source = (
        "import os\n"
        "import fnmatch\n"
        "import matplotlib.pyplot as plt\n"
        "from matplotlib.figure import Figure\n"
        f"_ALLOWED_SAVE_PATTERNS = {pattern_literal}\n"
        "_ORIG_FIG_SAVEFIG = Figure.savefig\n"
        "_ORIG_PLT_SAVEFIG = plt.savefig\n"
        "def _allow_fname(path_like):\n"
        "    name = os.path.basename(str(path_like))\n"
        "    return any(fnmatch.fnmatch(name, pat) for pat in _ALLOWED_SAVE_PATTERNS)\n"
        "def _filtered_fig_savefig(self, fname, *args, **kwargs):\n"
        "    if _allow_fname(fname):\n"
        "        return _ORIG_FIG_SAVEFIG(self, fname, *args, **kwargs)\n"
        "    return None\n"
        "def _filtered_plt_savefig(fname, *args, **kwargs):\n"
        "    if _allow_fname(fname):\n"
        "        return _ORIG_PLT_SAVEFIG(fname, *args, **kwargs)\n"
        "    return None\n"
        "Figure.savefig = _filtered_fig_savefig\n"
        "plt.savefig = _filtered_plt_savefig\n"
        "print(f'Save filter enabled: {_ALLOWED_SAVE_PATTERNS}')\n"
    )
    return nbformat.v4.new_code_cell(source)


def run_pooled_figure_core(
    config: PipelineConfig,
    *,
    end_cell: int,
    allowed_patterns: list[str],
    task_name: str = "custom_pooled_figure",
) -> dict[str, str]:
    """Run a specific segment of the pooled notebook.

    This is the core figure runner. Notebook cells should call this directly with
    explicit inputs instead of relying on higher-level wrappers.
    """
    pooled_nb_path = config.notebooks_root / "PooledFigure_CKII_Stats_V2.ipynb"
    if not pooled_nb_path.exists():
        raise FileNotFoundError(f"Pooled notebook not found: {pooled_nb_path}")

    # Validate PSD contract if requested cell range touches PSD section.
    if int(end_cell) >= 67 and config.pooled.run_psd_sections and config.pooled.cs_plc_only:
        for animal_id in config.animals:
            _validate_psd_contract(animal_id, config)

    pooled_out_dir = config.figures_root / "CKII_pooled"
    pooled_out_dir.mkdir(parents=True, exist_ok=True)
    start_ns = datetime.now(timezone.utc).timestamp() * 1_000_000_000

    nb = nbformat.read(str(pooled_nb_path), as_version=4)
    nb = _patch_pooled_notebook(nb, config)
    nb.cells.insert(2, _build_save_filter_cell(list(allowed_patterns)))

    # Execute only required prefix of notebook.
    end_cell_patched = int(end_cell) + 1  # +1 for inserted save-filter cell
    nb.cells = nb.cells[: end_cell_patched + 1]

    save_path = None
    if config.cache.save_executed_notebooks:
        safe_key = re.sub(r"[^A-Za-z0-9_]+", "_", str(task_name))
        save_path = config.notebooks_root / "_executed_cache" / f"Pooled_{safe_key}_executed.ipynb"

    _execute_notebook(nb, cwd=config.notebooks_root, save_path=save_path)

    generated: dict[str, str] = {}
    for svg_path in sorted(pooled_out_dir.glob("*.svg")):
        if svg_path.stat().st_mtime_ns < int(start_ns):
            continue
        if any(fnmatch.fnmatch(svg_path.name, pat) for pat in allowed_patterns):
            generated[svg_path.name] = str(svg_path)
    return generated


def run_pooled_figure(config: PipelineConfig, figure_key: str) -> dict[str, str]:
    if figure_key not in POOLED_FIGURE_TASKS:
        valid = ", ".join(sorted(POOLED_FIGURE_TASKS.keys()))
        raise ValueError(f"Unknown figure_key={figure_key!r}. Valid keys: {valid}")

    task = POOLED_FIGURE_TASKS[figure_key]
    return run_pooled_figure_core(
        config,
        end_cell=int(task["end_cell"]),
        allowed_patterns=list(task["patterns"]),
        task_name=figure_key,
    )


